from pathlib import Path
Path('interface/src/test/setup.ts').write_text("""function createMemoryStorage(): Storage {
\tconst values = new Map<string, string>();
\treturn {
\t\tget length() { return values.size; },
\t\tclear() { values.clear(); },
\t\tgetItem(key: string) { return values.get(String(key)) ?? null; },
\t\tkey(index: number) { return Array.from(values.keys())[index] ?? null; },
\t\tremoveItem(key: string) { values.delete(String(key)); },
\t\tsetItem(key: string, value: string) { values.set(String(key), String(value)); }
\t};
}

function exposeWindowStorage(name: 'localStorage' | 'sessionStorage') {
\tif (typeof window === 'undefined') return;
\tlet storage: Storage | undefined;
\ttry { storage = window[name]; } catch { storage = undefined; }
\tstorage ??= createMemoryStorage();
\tObject.defineProperty(window, name, { configurable: true, value: storage, writable: true });
\tObject.defineProperty(globalThis, name, { configurable: true, value: storage, writable: true });
}

exposeWindowStorage('localStorage');
exposeWindowStorage('sessionStorage');
""")
